'use strict';
function emptyLoop(){return {start:0,end:null,enabled:false,video:''}}
function loopValid(loop,duration){return Number.isFinite(loop.start)&&Number.isFinite(loop.end)&&loop.start>=0&&loop.end-loop.start>=1&&duration>0&&loop.end<=duration+.05}
function savedLoop(d){return d.loop?{...d.loop}:emptyLoop()}
function resetLoop(d){d.loop=emptyLoop();d.loopWaiting=false;d.loopLastSeek=0;paintLoop(d)}
function restoreLoop(d,value){resetLoop(d);if(value&&Number.isFinite(value.start)&&Number.isFinite(value.end)&&value.start>=0&&value.end-value.start>=1&&typeof value.video==='string'&&value.video){d.loop={start:value.start,end:value.end,video:value.video,enabled:!!value.enabled};d.loopWaiting=true;paintLoop(d)}}
function paintLoop(d,message){if(!d.loopUI)return;const l=d.loop,u=d.loopUI;if(document.activeElement!==u.start)u.start.value=l.start.toFixed(1);if(document.activeElement!==u.end)u.end.value=l.end==null?'':l.end.toFixed(1);u.toggle.setAttribute('aria-pressed',String(l.enabled));u.toggle.textContent='↻';u.toggle.title=l.enabled?'Désactiver la boucle':'Activer la boucle';u.toggle.setAttribute('aria-label',u.toggle.title+' '+d.letter);u.info.textContent=message||''}
function loopVideo(d){return d.player.getVideoData()?.video_id||''}
function loopSeek(d,play){d.loopLastSeek=performance.now();d.player.seekTo(d.loop.start,true);if(play)d.player.playVideo()}
function loopTick(d){if(!d.ready||!d.loopUI)return;const u=d.loopUI;u.fieldset.disabled=false;const video=loopVideo(d),l=d.loop;if(!video)return;if(d.loopWaiting){if(video!==l.video)return;d.loopWaiting=false;}if(l.video&&video!==l.video){resetLoop(d);return;}const duration=d.player.getDuration();if(l.enabled&&duration>0&&!loopValid(l,duration)){l.enabled=false;paintLoop(d,'Repères hors du morceau : corrigez la sortie.');return;}if(!l.enabled||!loopValid(l,duration))return;const state=d.player.getPlayerState(),time=d.player.getCurrentTime();if(state!==1&&state!==0)return;if(performance.now()-(d.loopLastSeek||0)<800)return;if(time>=l.end||time<l.start-.15||state===0)loopSeek(d,state===0)}
function initLoops(){decks.forEach(d=>{const box=document.createElement('div');box.className='loop-panel';box.innerHTML=`<fieldset disabled aria-label="Boucle de passage ${d.letter}"><div class="loop-points"><div class="loop-point"><button type="button" class="mark-in" aria-label="Placer l’entrée de boucle ${d.letter}" title="Placer l’entrée à la position actuelle">Entrée ↓</button><input class="loop-in" aria-label="Entrée de boucle ${d.letter} en secondes" type="number" min="0" step="0.1" value="0"></div><div class="loop-point"><button type="button" class="mark-out" aria-label="Placer la sortie de boucle ${d.letter}" title="Placer la sortie à la position actuelle">Sortie ↓</button><input class="loop-out" aria-label="Sortie de boucle ${d.letter} en secondes" type="number" min="0" step="0.1" placeholder="s"></div><button type="button" class="loop-toggle" aria-label="Activer la boucle ${d.letter}" aria-pressed="false" title="Activer la boucle">↻</button><button type="button" class="loop-clear" title="Effacer les repères" aria-label="Effacer la boucle ${d.letter}">×</button></div><div class="loop-info" role="status"></div></fieldset>`;d.root.querySelector('.listhead').before(box);d.loopUI={fieldset:box.querySelector('fieldset'),start:box.querySelector('.loop-in'),end:box.querySelector('.loop-out'),toggle:box.querySelector('.loop-toggle'),info:box.querySelector('.loop-info')};resetLoop(d);
function edit(which,value){const duration=d.player.getDuration(),video=loopVideo(d);if(!video||duration<=0){paintLoop(d,'Attendez que la durée du morceau soit disponible.');return}if(!Number.isFinite(value)||value<0||value>duration){paintLoop(d,'Repère invalide : indiquez un temps dans le morceau.');return}d.loopWaiting=false;d.loop.video=video;d.loop[which]=Math.round(value*10)/10;if(!loopValid(d.loop,duration))d.loop.enabled=false;paintLoop(d, d.loop.end!=null&&!loopValid(d.loop,duration)?'La sortie doit suivre l’entrée d’au moins 1 seconde.':undefined)}
box.querySelector('.mark-in').onclick=()=>edit('start',d.player.getCurrentTime());box.querySelector('.mark-out').onclick=()=>edit('end',d.player.getCurrentTime());d.loopUI.start.onchange=()=>edit('start',d.loopUI.start.value===''?NaN:Number(d.loopUI.start.value));d.loopUI.end.onchange=()=>edit('end',d.loopUI.end.value===''?NaN:Number(d.loopUI.end.value));d.loopUI.toggle.onclick=()=>{if(d.loop.enabled){d.loop.enabled=false;paintLoop(d);return}if(!loopValid(d.loop,d.player.getDuration())){paintLoop(d,'Définissez entrée et sortie, espacées d’au moins 1 seconde.');return}d.loop.video=loopVideo(d);d.loop.enabled=true;d.loopWaiting=false;const playing=d.player.getPlayerState()===1;loopSeek(d,false);if(!playing)d.player.pauseVideo();paintLoop(d)};box.querySelector('.loop-clear').onclick=()=>resetLoop(d);});}
initLoops();setInterval(()=>decks.forEach(loopTick),100);
